calls.arg:
gh pr view 370 --json body -q .body > /tmp/pr370_body.md
wc -l /tmp/pr370_body.md
cat -A /tmp/pr370_body.md | grep -n '\$$' | head -5
echo "---checking consecutive nonblank lines without block markers---"
awk 'BEGIN{prev=""; prevblank=1}
{
  line=$0
  isblank = (line ~ /^[[:space:]]*$/)
  if (!isblank && !prevblank) {
    # check if either prev or current line begins with block marker
    print NR": "line
  }
  prevblank = isblank
}' /tmp/pr370_body.md

python3 - <<'EOF'
import re
lines = open('/tmp/pr370_body.md').read().split('\n')
in_fence = False
def is_block_marker(line):
    s = line.lstrip(' ')
    if re.match(r'^(#|\-|\*|\+|\d+\.|\>|\|)', s):
        return True
    if line.startswith('    '):
        return True
    if s.startswith('```') or s.startswith('~~~'):
        return True
    return False

violations = []
prev = None
in_fence = False
for i, line in enumerate(lines):
    s = line.strip()
    if s.startswith('```') or s.startswith('~~~'):
        in_fence = not in_fence
        prev = None
        continue
    if in_fence:
        continue
    if s.startswith('<!--'):
        prev = None
        continue
    if s.startswith('>'):
        prev = None
        continue
    if s == '':
        prev = None
        continue
    if prev is not None:
        prevline = prev
        if re.match(r'^(\-|\*|\+)\s|\d+\.\s', prevline.strip()) and line.startswith((' ','\t')) and not re.match(r'^\s*(\-|\*|\+)\s|\s*\d+\.\s', line):
            violations.append((i+1, 'indented continuation', line))
        elif not is_block_marker(line) and not is_block_marker(prevline):
            violations.append((i+1, 'consecutive non-empty', repr(line)))
    prev = line

for v in violations:
    print(v)
print(len(violations), "violations")
EOF
